class Solution {
public:
    int numberOfPermutations(int n, vector<vector<int>>& requirements) {
        long long MOD = 1e9 + 7;
        unordered_map<int, int> req_map;
        int max_k = 0;
        for (const auto& r : requirements) {
            req_map[r[0]] = r[1];
            max_k = max(max_k, r[1]);
        }
        if (req_map.count(0) && req_map[0] != 0) return 0;
        vector<long long> dp(max_k + 1, 0);
        dp[0] = 1;
        for (int i = 1; i < n; ++i) {
            vector<long long> new_dp(max_k + 1, 0);
            vector<long long> pref(max_k + 2, 0);
            for (int k = 0; k <= max_k; ++k) {
                pref[k + 1] = (pref[k] + dp[k]) % MOD;
            }
            for (int k = 0; k <= max_k; ++k) {
                int low = max(0, k - i);
                new_dp[k] = (pref[k + 1] - pref[low] + MOD) % MOD;
            }
            if (req_map.count(i)) {
                int target = req_map[i];
                for (int k = 0; k <= max_k; ++k) {
                    if (k != target) new_dp[k] = 0;
                }
            }
            dp = move(new_dp);
        }
        return dp[req_map[n - 1]];
    }
};

class Solution {
    public int numberOfPermutations(int n, int[][] requirements) {
        long MOD = 1_000_000_007L;
        Map<Integer, Integer> reqMap = new HashMap<>();
        int maxK = 0;
        for (int[] r : requirements) {
            reqMap.put(r[0], r[1]);
            maxK = Math.max(maxK, r[1]);
        }
        if (reqMap.containsKey(0) && reqMap.get(0) != 0) return 0;
        long[] dp = new long[maxK + 1];
        dp[0] = 1;
        for (int i = 1; i < n; ++i) {
            long[] newDp = new long[maxK + 1];
            long[] pref = new long[maxK + 2];
            for (int k = 0; k <= maxK; ++k) {
                pref[k + 1] = (pref[k] + dp[k]) % MOD;
            }
            for (int k = 0; k <= maxK; ++k) {
                int low = Math.max(0, k - i);
                newDp[k] = (pref[k + 1] - pref[low] + MOD) % MOD;
            }
            if (reqMap.containsKey(i)) {
                int target = reqMap.get(i);
                for (int k = 0; k <= maxK; ++k) {
                    if (k != target) newDp[k] = 0;
                }
            }
            dp = newDp;
        }
        return (int) dp[reqMap.get(n - 1)];
    }
}

var numberOfPermutations = function(n, requirements) {
    const MOD = 1000000007n;
    const reqMap = new Map();
    let maxK = 0;
    for (const [end, cnt] of requirements) {
        reqMap.set(end, cnt);
        if (cnt > maxK) maxK = cnt;
    }
    if (reqMap.has(0) && reqMap.get(0) !== 0) return 0;
    let dp = new BigInt64Array(maxK + 1);
    dp[0] = 1n;
    for (let i = 1; i < n; ++i) {
        const newDp = new BigInt64Array(maxK + 1);
        const pref = new BigInt64Array(maxK + 2);
        for (let k = 0; k <= maxK; ++k) {
            pref[k + 1] = (pref[k] + dp[k]) % MOD;
        }
        for (let k = 0; k <= maxK; ++k) {
            const low = Math.max(0, k - i);
            newDp[k] = (pref[k + 1] - pref[low] + MOD) % MOD;
        }
        if (reqMap.has(i)) {
            const target = reqMap.get(i);
            for (let k = 0; k <= maxK; ++k) {
                if (k !== target) newDp[k] = 0n;
            }
        }
        dp = newDp;
    }
    return Number(dp[reqMap.get(n - 1)]);
};
